        {
            button.BackColor = color;
            button.BorderColor = color == System.Drawing.Color.FromArgb(250, 253, 251) ? System.Drawing.Color.FromArgb(165, 196, 181) : System.Drawing.Color.FromArgb(21, 102, 88);
            button.BorderSize = 1;
            button.CornerRadius = 13;
            button.FlatAppearance.BorderSize = 0;
            button.FlatStyle = System.Windows.Forms.FlatStyle.Flat;
            button.Font = new System.Drawing.Font(FuntinoControlCenter.UI.AppFontManager.VazirmatnFamily, 8.5F, System.Drawing.FontStyle.Bold);
            button.ForeColor = color == System.Drawing.Color.FromArgb(250, 253, 251) ? System.Drawing.Color.FromArgb(27, 67, 57) : System.Drawing.Color.White;
            button.Image = image;
            button.ImageAlign = System.Drawing.ContentAlignment.MiddleRight;
            button.Margin = new System.Windows.Forms.Padding(4, 3, 4, 3);
            button.MinimumSize = new System.Drawing.Size(width, height);
            button.Padding = new System.Windows.Forms.Padding(10, 0, 10, 0);
            button.RightToLeft = System.Windows.Forms.RightToLeft.Yes;
            button.Size = new System.Drawing.Size(width, height);
            button.Text = text;
            button.TextAlign = System.Drawing.ContentAlignment.MiddleCenter;
            button.TextImageRelation = System.Windows.Forms.TextImageRelation.ImageBeforeText;
            button.UseVisualStyleBackColor = false;
        }
